L["Line Spacing"] = "行間距"
L["Adds vertical space between a quest's objective lines, across the whole tracker. 0 keeps the default spacing."] = "全局調整任務目標行之間的垂直間距。填0使用預設間距。"
L["Header Spacing"] = "標題間距"
L["Adds or removes space around section headers and beneath each quest's title. 0 keeps the default spacing."] = "調整板塊標題四周以及每個任務標題下方間距。填0使用預設間距。"
L["Quest Rows"] = "任務行"
