L["Gives campaign, legendary, dungeon and raid entries their own card color. Anything else uses the plain background color above."] = "戰役、傳說、地下城、團隊副本任務使用獨立卡片顏色，其餘任務使用普通背景色。"
L["Campaign"] = "戰役"
